component_data_script:
rows = props.get("heads") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

heads = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	while len(parts) < 5:
		parts.append("")
	heads.append({"mark": parts[0], "title": parts[1], "line": parts[2], "item": parts[3], "amount": parts[4]})
for i in range(len(heads)):
	head = heads[i]
	head["i"] = str(i)
	# four letterhead styles, dealt in turn
	head["style"] = str(i % 4 + 1)
count = len(heads)
step = 22
if count > 1:
	step = round((94 - 28) / (count - 1), 3)
component.heads = heads
component.step = str(step) + "%"
